package pl.zagranietyper.provider;
import org.junit.jupiter.api.Test;import pl.zagranietyper.model.*;import java.math.BigDecimal;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class FotMobPeriodStatisticsProviderTest {@Test void additiveGuardAndKnownZeroAreConservative(){var values=List.of(v(FootballPeriodStatisticsSnapshot.Period.FULL_MATCH,2),v(FootballPeriodStatisticsSnapshot.Period.FIRST_HALF,0),v(FootballPeriodStatisticsSnapshot.Period.SECOND_HALF,2));assertTrue(FotMobPeriodStatisticsProvider.additiveSafe(values));assertEquals(BigDecimal.ZERO,values.get(1).value());var bad=List.of(v(FootballPeriodStatisticsSnapshot.Period.FULL_MATCH,3),v(FootballPeriodStatisticsSnapshot.Period.FIRST_HALF,0),v(FootballPeriodStatisticsSnapshot.Period.SECOND_HALF,2));assertFalse(FotMobPeriodStatisticsProvider.additiveSafe(bad));assertThrows(IllegalArgumentException.class,()->new FootballPeriodStatisticsSnapshot.Value(FootballPeriodStatisticsSnapshot.Period.FIRST_HALF,FootballFixtureStatisticType.CORNERS,FootballFixtureStatisticsSnapshot.TeamSide.HOME,null,FootballFixtureStatisticsSnapshot.ValueStatus.KNOWN,"Corners"));}private static FootballPeriodStatisticsSnapshot.Value v(FootballPeriodStatisticsSnapshot.Period p,int n){return new FootballPeriodStatisticsSnapshot.Value(p,FootballFixtureStatisticType.CORNERS,FootballFixtureStatisticsSnapshot.TeamSide.HOME,BigDecimal.valueOf(n),FootballFixtureStatisticsSnapshot.ValueStatus.KNOWN,"Corners");}}
